package com.vandorlabs.client;
import com.google.gson.*;
import com.vandorlabs.programmer.ProgrammerBlock;
import java.nio.file.*;
import net.minecraft.util.EnumFacing;
import net.minecraft.util.math.BlockPos;
/** Actual support, light, redstone and fluid getters, kept separate from visual/ray geometry. */
public final class ProgrammerPropertiesLegacyChecks {
 public static void main(String[] args)throws Exception{net.minecraft.init.Bootstrap.register();ProgrammerBlock block=new ProgrammerBlock();NonRenderingChecks.MemoryWorld world=new NonRenderingChecks.MemoryWorld(false);BlockPos pos=new BlockPos(0,80,0);JsonArray rows=new JsonArray();java.lang.reflect.Method flow=net.minecraft.block.BlockDynamicLiquid.class.getDeclaredMethod("canFlowInto",net.minecraft.world.World.class,BlockPos.class,net.minecraft.block.state.IBlockState.class);flow.setAccessible(true);for(int meta=0;meta<16;meta++){varState(block,world,pos,meta,flow,rows);}JsonObject root=new JsonObject();root.addProperty("schema",1);root.add("cases",rows);StringBuilder golden=new StringBuilder();for(byte value:java.security.MessageDigest.getInstance("SHA-256").digest(root.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8)))golden.append(String.format(java.util.Locale.ROOT,"%02x",value&255));if(!golden.toString().equals("b7c05fdd08484bb2004d097067fefed1150aaa84a1b701d5b54e8be4c996d1b3"))throw new AssertionError("Programmer property contract changed: "+golden);root.addProperty("golden",golden.toString());Path output=Paths.get(System.getProperty("vandorlabs.programmerPropertiesReference","build/test-artifacts/programmer-properties-forge.json"));Files.createDirectories(output.toAbsolutePath().getParent());try(java.io.Writer writer=Files.newBufferedWriter(output)){new Gson().toJson(root,writer);}System.out.println("Actual programmer properties Source PASS cases="+rows.size()+" golden="+golden);}
 private static void varState(ProgrammerBlock block,NonRenderingChecks.MemoryWorld world,BlockPos pos,int meta,java.lang.reflect.Method flow,JsonArray rows)throws Exception{net.minecraft.block.state.IBlockState state=block.getStateFromMeta(meta);world.states.put(pos,state);JsonObject row=new JsonObject();row.addProperty("meta",meta);row.addProperty("normalCube",block.isNormalCube(state,world,pos));row.addProperty("fullCube",block.isFullCube(state));row.addProperty("opaqueCube",block.isOpaqueCube(state));row.addProperty("suffocation",block.causesSuffocation(state));row.addProperty("passable",block.isPassable(world,pos));row.addProperty("lightOpacity",block.getLightOpacity(state,world,pos));row.addProperty("light",block.getLightValue(state,world,pos));row.addProperty("ao",block.getAmbientOcclusionLightValue(state));JsonArray sides=new JsonArray(),faces=new JsonArray();for(EnumFacing side:EnumFacing.values()){sides.add(block.isSideSolid(state,world,pos,side));faces.add(block.getBlockFaceShape(world,state,pos,side).name());}row.add("solidSides",sides);row.add("faceShapes",faces);for(boolean lava:new boolean[]{false,true}){row.addProperty(lava?"lavaFlow":"waterFlow",(Boolean)flow.invoke(lava?net.minecraft.init.Blocks.FLOWING_LAVA:net.minecraft.init.Blocks.FLOWING_WATER,world,pos,state));row.addProperty(lava?"lavaBucket":"waterBucket",((net.minecraft.item.ItemBucket)(lava?net.minecraft.init.Items.LAVA_BUCKET:net.minecraft.init.Items.WATER_BUCKET)).tryPlaceContainedLiquid(null,world,pos));if(world.getBlockState(pos)!=state)throw new AssertionError("Source fluid replaced programmer");}rows.add(row);}
}
